                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                # Extend outward from an endpoint only if it is not attached
                # orthogonally to another non-background cell.
                for endpoint, sr, sc in ((run[0], -dr, -dc), (run[-1], dr, dc)):
                    er, ec = endpoint
                    attached = any(
                        0 <= er + vr < h and 0 <= ec + vc < w
                        and grid[er + vr][ec + vc] != bg
                        for vr, vc in ((1, 0), (-1, 0), (0, 1), (0, -1))
                    )
                    if attached:
                        continue

                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
